import "aos/dist/aos.css";
import {
    FaCalculator,
    FaFileInvoiceDollar,
    FaChartLine,
    FaBalanceScale,
    FaClipboardCheck,
    FaWhatsapp,
    FaUniversity,
} from "react-icons/fa";
import {
    CoverCity3, TeamTax1, TeamTax2, TeamTax3, Tenant10, Tenant11, Tenant12,
    Tenant13, Tenant14, Tenant15, Tenant16, Tenant17, Tenant18,
    Tenant19, Tenant20, Tenant21, Tenant22, Tenant23, Tenant24, Tenant6, Tenant8, Tenant9
} from "../../asset/image";
import { useCallback, useContext, useEffect, useRef, useState } from "react";
import AppContext from "../../../Context";

function TaxAccounting() {
    //-----------------------STATE VIEWS-----------------------//
    const { language } = useContext(AppContext);
    const taxServices = [
        {
            title:
                language === "id"
                    ? "Kepatuhan Pajak"
                    : "Tax Compliance",
            description:
                language === "id"
                    ? "Pengelolaan dan pelaporan pajak sesuai dengan peraturan yang berlaku untuk memastikan kepatuhan dan meminimalkan risiko."
                    : "Tax management and reporting in accordance with applicable regulations to ensure compliance and minimize risks.",
            icon: FaFileInvoiceDollar,
        },
        {
            title:
                language === "id"
                    ? "Perencanaan Pajak"
                    : "Tax Planning",
            description:
                language === "id"
                    ? "Perencanaan pajak strategis untuk mengoptimalkan efisiensi fiskal dan mendukung pertumbuhan bisnis Anda."
                    : "Strategic tax planning to optimize fiscal efficiency and support your business growth.",
            icon: FaBalanceScale,
        },
        {
            title:
                language === "id"
                    ? "Akuntansi & Pembukuan"
                    : "Accounting & Bookkeeping",
            description:
                language === "id"
                    ? "Pencatatan keuangan yang akurat dan sistematis untuk menjaga transparansi dan kesehatan keuangan perusahaan."
                    : "Accurate and systematic financial record-keeping to maintain transparency and the company’s financial health.",
            icon: FaCalculator,
        },
        {
            title:
                language === "id"
                    ? "Laporan Keuangan"
                    : "Financial Reporting",
            description:
                language === "id"
                    ? "Penyusunan laporan keuangan komprehensif sesuai standar akuntansi untuk kebutuhan internal maupun eksternal."
                    : "Preparation of comprehensive financial statements in accordance with accounting standards for internal and external purposes.",
            icon: FaChartLine,
        },
        {
            title:
                language === "id"
                    ? "Konsultasi Bisnis"
                    : "Business Advisory",
            description:
                language === "id"
                    ? "Layanan konsultasi strategis untuk mendukung pengambilan keputusan bisnis berbasis data."
                    : "Strategic advisory and consultation services to support data-driven business decision-making.",
            icon: FaClipboardCheck,
        },
        {
            title:
                language === "id"
                    ? "Dukungan Korporasi & Regulasi"
                    : "Corporate & Regulatory Support",
            description:
                language === "id"
                    ? "Dukungan administratif dan regulasi perusahaan termasuk perizinan, kepatuhan, dan pengurusan dokumen resmi."
                    : "Administrative and regulatory corporate support, including licensing, compliance, and official documentation processing.",
            icon: FaUniversity,
        },
    ];

    const teamMembers = [
        {
            name: "CINDY MINTAULI BORU S. ., SE., M.SC., AK., CTT., CA",
            photo: TeamTax1,
            certifications: [
                "Public Accountant License No. AB.1080",
                "Tax Litigation Counsel at the Indonesian Tax Court No. KHP-02355",
                "Certified Intermediate Tax Technician (ATPI) Brevet A & B \n No. REG.TP.78425.23.01.27.04.05.000.468 2023",
                "Certified Tax Technician (CTT-ATPI) \n No. Reg CTT 04.05.000.001.896 2023",
                "Certified Chartered Accountant (CA-IAI) No. 11.D48110",
                "Certified Xero Advisor No. 12649002",
            ],
        },
        {
            name: "Widodo, S.E., M.M.",
            photo: TeamTax2,
            certifications: [
                "Tax Litigation Counsel at the Indonesian Tax Court No. KHP-02538",
            ],
        },
        {
            name: "Syahru Ramadhan",
            photo: TeamTax3,
            certifications: [
                "Certified Tax Technician (CTT-ATPI) \n No. Reg CTT 04.05.000.020.012 2025",
                "Certified Intermediate Tax Technician (ATPI) Brevet A & B \n No. REG.TP 225.10.14.04.05.020.012 2025",
            ],
        },
    ];

    const WA_NUMBER = "6281213094426";

    const [currentTenantSlide, setCurrentTenantSlide] = useState(0);
    const tenantIntervalRef = useRef<NodeJS.Timeout | null>(null);
    const TENANTS_PER_SLIDE = 3;
    const tenantSlides = [];
    const tenants = [
        { name: "Tenant 8", logo: Tenant8 },
        { name: "Tenant 9", logo: Tenant9 },
        { name: "Tenant 10", logo: Tenant10 },
        { name: "Tenant 11", logo: Tenant11 },
        { name: "Tenant 12", logo: Tenant12 },
        { name: "Tenant 13", logo: Tenant13 },
        { name: "Tenant 14", logo: Tenant14 },
        { name: "Tenant 15", logo: Tenant15 },
        { name: "Tenant 16", logo: Tenant16 },
        { name: "Tenant 17", logo: Tenant17 },
        { name: "Tenant 18", logo: Tenant18 },
        { name: "Tenant 19", logo: Tenant19 },
        { name: "Tenant 6", logo: Tenant6 },
        { name: "Tenant 23", logo: Tenant23 },
        { name: "Tenant 24", logo: Tenant24 },
        { name: "Tenant 20", logo: Tenant20 },
        { name: "Tenant 21", logo: Tenant21 },
        { name: "Tenant 22", logo: Tenant22 },
    ];

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const rawMessage =
            language === "id"
                ? `Halo Regarde,\nSaya ingin berkonsultasi mengenai layanan ${serviceName}.\nMohon informasi lebih lanjut. Terima kasih.`
                : `Hello Regarde,\nI would like to consult regarding the ${serviceName} service.\nPlease provide further information. Thank you.`;

        return `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(rawMessage)}`;
    };

    const startTenantAutoSlide = useCallback(() => {
        if (tenantIntervalRef.current) {
            clearInterval(tenantIntervalRef.current);
        }
        tenantIntervalRef.current = setInterval(() => {
            setCurrentTenantSlide((prev) => (prev + 1) % tenantSlides.length);
        }, 5000);
    }, [tenantSlides.length]);
    const nextTenantSlide = useCallback(() => {
        setCurrentTenantSlide((prev) => (prev + 1) % tenantSlides.length);
        startTenantAutoSlide();
    }, [tenantSlides.length, startTenantAutoSlide]);
    const prevTenantSlide = useCallback(() => {
        setCurrentTenantSlide(
            (prev) => (prev - 1 + tenantSlides.length) % tenantSlides.length
        );
        startTenantAutoSlide();
    }, [tenantSlides.length, startTenantAutoSlide]);
    useEffect(() => {
        startTenantAutoSlide();
        return () => {
            if (tenantIntervalRef.current) {
                clearInterval(tenantIntervalRef.current);
            }
        };
    }, [startTenantAutoSlide]);
    for (let i = 0; i < tenants.length; i += TENANTS_PER_SLIDE) {
        tenantSlides.push(tenants.slice(i, i + TENANTS_PER_SLIDE));
    }
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-14">
            {/* COVER PHOTO */}
            <section
                className="relative w-full min-h-[80vh] md:min-h-[50vh] lg:min-h-[90vh] flex items-center"
                style={{
                    backgroundImage: `url(${CoverCity3})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                }}
            >
                {/* DARK OVERLAY */}
                <div className="absolute inset-0 bg-black/65" />

                {/* CONTENT */}
                <div
                    className="relative z-10 w-11/12 md:w-5/6 mx-auto text-white"
                    data-aos="fade-up"
                    data-aos-duration="1200"
                >

                    {/* HEADLINE */}
                    <h1
                        className="text-2xl md:text-4xl lg:text-5xl text-left pt-10 md:pt-0 lg:pt-3 font-bold leading-[1.35] md:leading-[1.35] lg:leading-[1.35] max-w-3xl"
                        data-aos="fade-right"
                        data-aos-delay="100"
                    >
                        {language === "id" ? (
                            <>
                                Pasar Tidak Pernah Berhenti,
                                <br />
                                Uang Tidak Pernah Tidur
                            </>
                        ) : (
                            <>
                                Market Never Stop,
                                <br />
                                Money Never Sleep
                            </>
                        )}
                    </h1>

                    {/* CTA BUTTON */}
                    <div
                        className="mt-8 flex justify-start"
                        data-aos="fade-up"
                        data-aos-delay="300"
                    >
                        <a
                            href={getWaLink('Tax & Accounting')}
                            className="inline-flex items-center gap-2 bg-red-500 hover:bg-red-600 text-white font-semibold px-3 py-2 rounded-lg transition"
                        >
                            {language === 'id' ? 'Hubungi Kami' : 'Contact Us'}
                            <span className="text-xl">›</span>
                        </a>
                    </div>

                    {/* CLIENT LOGOS */}
                    <div
                        className="mt-16 flex flex-wrap gap-2 md:gap-3 lg:gap-4 items-center justify-start opacity-80"
                        data-aos="fade-up"
                        data-aos-delay="500"
                    >
                        <img alt="logo2" src={Tenant6} className="h-12 md:h-14 lg:h-32 object-contain filter brightness-0 invert opacity-70" />
                        <img alt="logo3" src={Tenant10} className="h-12 md:h-14 lg:h-32 object-contain filter brightness-0 invert opacity-70" />
                        <img alt="logo3" src={Tenant11} className="h-12 md:h-14 lg:h-32 object-contain filter brightness-0 invert opacity-70" />
                        <img alt="logo3" src={Tenant12} className="h-12 md:h-14 lg:h-32 object-contain filter brightness-0 invert opacity-70" />
                        <img alt="logo3" src={Tenant13} className="h-12 md:h-14 lg:h-32 object-contain filter brightness-0 invert opacity-70" />
                    </div>

                    {/* STATS */}
                    <div
                        className="mt-8 grid grid-cols-3 md:grid-cols-3 lg:grid-cols-3 gap-8 text-center sm:text-left"
                        data-aos="fade-up"
                        data-aos-delay="700"
                    >
                        <div>
                            <p className="text-4xl font-bold">3500+</p>
                            <p className="text-sm opacity-80">
                                {language === "id" ? "Klien Puas" : "Happy Client"}
                            </p>
                        </div>

                        <div>
                            <p className="text-4xl font-bold">15+</p>
                            <p className="text-sm opacity-80">
                                {language === "id" ? "Tahun Pengalaman" : "Years Experience"}
                            </p>
                        </div>

                        <div>
                            <p className="text-4xl font-bold">98%</p>
                            <p className="text-sm opacity-80">
                                {language === "id" ? "Tingkat Keberhasilan" : "Success Engagements"}
                            </p>
                        </div>
                    </div>
                </div>
            </section>

            {/* ABOUT */}
            <section data-aos="zoom-out" className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-primary-black-500 mb-4 mt-24">
                        {language === "id" ? "Pajak & Akuntansi" : "Tax & Accounting"}
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-primary-black-500 max-w-2xl mx-auto mb-4">
                        {language === "id"
                            ? "Regarde adalah firma konsultan profesional terkemuka di Indonesia dengan pengalaman lebih dari 15 tahun. Kami menyediakan layanan pajak, keuangan, akuntansi, dan audit untuk perusahaan domestik maupun internasional."
                            : "Regarde is a leading professional consulting firm in Indonesia with over 15 years of experience. We provide tax, finance, accounting, and audit services to domestic and international corporations."}
                    </p>

                    {/* DESCRIPTION */}
                    <p className="text-primary-black-500 max-w-2xl mx-auto mb-14">
                        {language === "id"
                            ? "Didukung oleh hubungan yang kuat dengan regulator dan pemangku kepentingan utama, kami menghadirkan solusi yang patuh regulasi dan bernilai tambah dengan menjunjung tinggi profesionalisme, komunikasi transparan, kerahasiaan klien yang ketat, serta kepatuhan terhadap kode etik profesi."
                            : "Supported by strong relationships with regulators and key stakeholders, we deliver compliant and value-driven solutions while upholding the highest standards of professionalism, transparent communication, strict client confidentiality, and adherence to professional codes of ethics"}
                    </p>

                </div>
            </section>

            {/* OUR PROFESSIONAL TEAM */}
            <section className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto">

                    {/* Heading */}
                    <div className="text-center mb-20" data-aos="fade-up">
                        <h2 className="text-4xl font-black text-primary-black-500 mb-4">
                            {language === "id" ? "Tim Profesional Kami" : "Our Professional Team"}
                        </h2>

                        <div className="w-24 h-[2px] bg-primary-black-500 mx-auto mb-6" />

                        <p className="text-gray-500 max-w-2xl mx-auto leading-relaxed">
                            {language === "id"
                                ? "Para profesional berpengalaman yang berdedikasi untuk menghadirkan solusi keuangan yang terpercaya, patuh regulasi, dan strategis."
                                : "Experienced professionals dedicated to delivering trusted, compliant, and strategic financial solutions."}
                        </p>
                    </div>

                    {/* Vertical Cards */}
                    <div className="space-y-20">
                        {teamMembers.map((member, i) => (
                            <div
                                key={i}
                                data-aos="fade-up"
                                data-aos-delay={i * 150}
                                className=" group relative flex flex-col md:flex-row items-stretch gap-10"
                            >
                                {/* Photo */}
                                <div className="md:w-1/3 relative overflow-hidden rounded-3xl">
                                    <img
                                        src={member.photo}
                                        alt={member.name}
                                        className="h-full object-cover transition duration-700 ease-out group-hover:scale-105"
                                    />

                                    <div className="absolute inset-0bg-gradient-to-t from-black/30 via-transparent to-transparentopacity-80" />
                                </div>

                                {/* Content */}
                                <div
                                    className=" md:w-2/3 bg-gray-50 rounded-3xl p-10 shadow-sm transition-all duration-500 group-hover:-translate-y-2 group-hover:shadow-xl"
                                >
                                    <h3 className="text-xl font-bold text-primary-black-500 mb-6 leading-snug">
                                        {member.name}
                                    </h3>

                                    <div className="w-16 h-[2px] bg-primary-blue-600 mb-6" />

                                    <ul className="space-y-3 text-gray-600 leading-relaxed">
                                        {member.certifications.map((cert, index) => (
                                            <li
                                                key={index}
                                                className="flex items-start gap-3"
                                            >
                                                <span className="mt-2 w-2 h-2 rounded-full bg-primary-blue-600 flex-shrink-0" />
                                                <span className="w-full text-left text-sm whitespace-pre-line">{cert}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* TAX & ACCOUNTING DETAIL */}
            <section data-aos="zoom-out" className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">
                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {taxServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-primary-blue-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-primary-black-500">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-primary-black-500 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>

            {/* OUR TENANTS */}
            <section className="py-20 relative">
                <div className="w-full md:w-full lg:w-11/12 mx-auto text-center px-1 md:px-0 lg:px-0">
                    <h2
                        data-aos="zoom-in"
                        className="text-4xl font-black text-primary-black-500 mb-12"
                    >
                        {language === 'id' ? 'Klien Kami' : 'Our Clients'}
                    </h2>

                    {/* SLIDER */}
                    <div className="w-full relative ">
                        <div className="overflow-hidden mx-10 md:mx-16 lg:mx-24">
                            {/* TRACK */}
                            <div
                                className="flex transition-transform duration-700 ease-in-out"
                                style={{
                                    transform: `translateX(-${currentTenantSlide * 100}%)`,
                                }}
                            >
                                {tenantSlides.map((slide, slideIndex) => (
                                    <div
                                        key={slideIndex}
                                        className="w-full flex-shrink-0 grid grid-cols-3 gap-8 items-center justify-center"
                                    >
                                        {slide.map((tenant, i) => (
                                            <div
                                                key={i}
                                                className="flex items-center justify-center"
                                            >
                                                <img
                                                    src={tenant.logo}
                                                    alt={tenant.name}
                                                    className="h-20 md:h-24 lg:h-36 object-contain opacity-100 transition"
                                                />
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* PREV */}
                        <button
                            onClick={prevTenantSlide}
                            className="absolute left-0 top-1/2 -translate-y-1/2 bg-black/40 hover:bg-black/60 text-white w-10 h-10 rounded-full flex items-center justify-center transition"
                        >
                            ❮
                        </button>

                        {/* NEXT */}
                        <button
                            onClick={nextTenantSlide}
                            className="absolute right-0 top-1/2 -translate-y-1/2 bg-black/40 hover:bg-black/60 text-white w-10 h-10 rounded-full flex items-center justify-center transition"
                        >
                            ❯
                        </button>
                    </div>

                    {/* DOTS */}
                    <div className="flex justify-center gap-2 mt-8">
                        {tenantSlides.map((_, index) => (
                            <button
                                key={index}
                                onClick={() => {
                                    setCurrentTenantSlide(index);
                                    startTenantAutoSlide();
                                }}
                                className={`w-3 h-3 rounded-full transition-all
                                    ${index === currentTenantSlide
                                        ? "bg-primary-blue-700 scale-110"
                                        : "bg-gray-300 hover:bg-gray-400"}
                                `}
                                aria-label={`Tenant slide ${index + 1}`}
                            />
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default TaxAccounting;